import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.address.*; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*;
public class WatchBotPhysicsTemp extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x005ddb9cL,0x004d6560L};for(long x:xs){Address a=toAddr(x);println("=== REF "+a+" ===");for(Reference r:getReferencesTo(a)){Function f=getFunctionContaining(r.getFromAddress());println(r.getFromAddress()+" "+r.getReferenceType()+" caller="+(f==null?"<none>":f.getName()));if(f!=null){DecompileResults z=d.decompileFunction(f,160,monitor);if(z.getDecompiledFunction()!=null){String c=z.getDecompiledFunction().getC();for(String l:c.split("\n"))if(l.contains("5ddb9c")||l.contains("4d6560")||l.contains("DAT_005DDB9C")||l.contains("FUN_004D6560"))println(l);}}}}d.dispose();}}
